import {rect,text,line,path,legend} from './svg.js';import {ramp} from './model.js';
export function draw(s,l){const {width:W,height:H,x,w,y,short}=l,dw=w*.19,off=(1-s.entry)*(-W)+s.exit*W;let out=legend([['die','晶粒'],['mold','模封材料'],['film','釋放膜'],['carrier','載板']],W);out+=`<defs><clipPath id="process"><rect x="0" y="${W<600?76:45}" width="${W}" height="${H-(W<600?108:77)}"/></clipPath></defs><g clip-path="url(#process)"><g transform="translate(${off} 0)">`;
if(s.release<1){const dy=s.release*(H+30);out+=rect(x-5,y+6+dy,w+10,7,'film')+rect(x-14,y+13+dy,w+28,23,'carrier')+rect(x-20,y+36+dy,32,12,'tool')+rect(x+w-12,y+36+dy,32,12,'tool');}
if(s.mold>0){out+=rect(x,y-70,w*s.mold,76,'mold',`style="fill:rgb(${229-22*s.cure},${218-26*s.cure},${206-28*s.cure})"`);out+=path(`M${x} ${y-70}l14 -10h${w*s.mold}l-14 10Z`,'mold outline');}
for(let i=0;i<3;i++){if(s.t<i*2.5+1)continue;const xx=x+w*(.08+.325*i),dy=(1-s.die[i])*(y+65),yy=y-37-dy;out+=rect(xx,yy,dw,43,'die')+path(`M${xx} ${yy}l9 -7h${dw}v7Z`,'die outline');out+=rect(xx,yy+39,dw,4,'active');for(let j=0;j<3;j++)out+=rect(xx+dw*(.15+j*.28),yy+37,dw*.13,6,'pad');if(i===0)out+=path(`M${xx+4} ${yy+4}h10v10Z`,'pad');if(s.t<3.5+i*2.5){const lift=ramp(s.t,3+i*2.5,3.5+i*2.5)*(y+50);out+=rect(xx+dw*.25,yy-17-lift,dw*.5,16,'tool')+line(xx+dw*.5,yy-17-lift,xx+dw*.5,yy-35-lift);}if(s.index===0&&s.die[i]===1)out+=text(xx+dw/2,y-52,i===0?'晶粒 A ▴':`晶粒 ${i===1?'B':'C'}`,'small');}
if(s.index===1){const py=y-87-(1-ramp(s.t,9,9.5)+ramp(s.t,14.3,15))*(y+80);out+=rect(x-16,py,w+32,14,'tool')+text(W/2,y-102,'壓縮模封 · 剖切顯示','caption');}
if(s.t>=17){const hh=(1-s.hold)*(y+50);out+=rect(x+w*.2,y-88-hh,w*.6,17,'tool')+line(W/2,y-88-hh,W/2,y-(short?88:110)-hh);if(s.hold===1)out+=short?text(W-12,y-64,'承托','small','end'):text(W/2,y-120,'背面吸持承托','caption');}
if(s.index===0)out+=text(W/2,y+74,'焊墊朝下 · 保留間距','caption');if(s.index===2)out+=text(W/2,y+74,'固化模封體固定三顆晶粒','caption');if(s.index===3)out+=text(W/2,Math.min(H-38,y+85),'載板與膜 → 釋放移除','caption');
if(s.index>=4){for(let i=0;i<3;i++){const xx=x+w*(.08+.325*i);out+=rect(xx-w*.035,y+10,dw+w*.07,17,'future','stroke-dasharray="5 4"');}out+=text(W/2,y+53,'共同表面 · RDL 尚未製作','caption');}
out+='</g></g>';if(s.exit>.99)out+=text(W/2,H/2,'下一組新晶粒與載板進場','caption');return out+text(W/2,H-14,'固定剖切 · 虛線為未來扇出範圍','small');}
